from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')

def replace_block(start_marker,end_marker,new_text):
    global s
    a=s.find(start_marker)
    if a<0:
        raise SystemExit('missing start: '+start_marker)
    b=s.find(end_marker,a)
    if b<0:
        raise SystemExit('missing end: '+end_marker)
    s=s[:a]+new_text+s[b:]

# Shipment status must support mixed received + waiting rows.
replace_block(
    'function purchaseShipmentGroups(){',
    '\nfunction purchaseShipmentTotals(',
    '''function purchaseShipmentStage(rows){const a=(rows||[]).map(purchaseStatus);if(a.includes('to_forwarder'))return 'to_forwarder';if(a.includes('to_me'))return 'to_me';if(a.includes('at_warehouse'))return 'at_warehouse';return 'received'}\nfunction purchaseShipmentGroups(){const map=new Map();for(const x of(state.purchases||[])){const key=String(x.shipmentId||x.id||'');if(!key)continue;let g=map.get(key);if(!g){g={key,rows:[],status:purchaseStatus(x),batch:x.batch||'',orderedAt:Number(x.orderedAt||x.date)||0,receivedAt:Number(x.receivedAt)||0,warehouseReceivedAt:Number(x.warehouseReceivedAt)||0,forwarderReceivedAt:Number(x.forwarderReceivedAt)||0};map.set(key,g)}g.rows.push(x);const ox=Number(x.orderedAt||x.date)||0;if(!g.orderedAt||ox<g.orderedAt)g.orderedAt=ox;g.receivedAt=Math.max(g.receivedAt,Number(x.receivedAt)||0);g.warehouseReceivedAt=Math.max(g.warehouseReceivedAt,Number(x.warehouseReceivedAt)||0);g.forwarderReceivedAt=Math.max(g.forwarderReceivedAt,Number(x.forwarderReceivedAt)||0)}for(const g of map.values())g.status=purchaseShipmentStage(g.rows);return [...map.values()].sort((a,b)=>(Number(b.receivedAt||b.warehouseReceivedAt||b.forwarderReceivedAt||b.orderedAt)||0)-(Number(a.receivedAt||a.warehouseReceivedAt||a.forwarderReceivedAt||a.orderedAt)||0))}'''
)

# Shipment sheet: show per-line state and open a checklist for release.
replace_block(
    'function openPurchaseShipment(encodedKey){',
    '\nfunction openEditPurchaseShipment(',
    '''function openPurchaseShipment(encodedKey){const rows=purchaseShipmentRows(encodedKey);if(!rows.length)return alert('Поставка не найдена');const first=rows[0],status=purchaseShipmentStage(rows),partial=rows.some(x=>purchaseStatus(x)==='received')&&rows.some(x=>purchaseStatus(x)!=='received'),t=purchaseShipmentTotals({rows}),key=encodeURIComponent(String(first.shipmentId||first.id||'')),label=partial?'Частично в продаже':status==='to_forwarder'?'Едет на склад':status==='to_me'?'Едет ко мне':status==='at_warehouse'?'Поступило на склад':'В продаже',badge=status==='to_me'?'purple':status==='at_warehouse'?'teal':status==='received'?'ok':'',date=status==='received'?rows.reduce((a,x)=>Math.max(a,Number(x.receivedAt)||0),0):status==='at_warehouse'?rows.reduce((a,x)=>Math.max(a,Number(x.warehouseReceivedAt)||0),0):status==='to_me'?rows.reduce((a,x)=>Math.max(a,Number(x.forwarderReceivedAt)||0),0):Number(first.orderedAt||first.date)||0,dateLabel=status==='received'?'В продажу с':status==='at_warehouse'?'На складе с':status==='to_me'?'Едет ко мне с':'Заказано',lines=rows.map(x=>{const qty=Number(x.qty)||0,buy=Number(x.buyTotal)||((Number(x.unitCost)||0)*qty),unitBuy=qty?buy/qty:0,withDelivery=Number(x.landedUnitCost)||(qty?(buy+(Number(x.delivery)||0))/qty:0),rs=purchaseStatus(x),rl=rs==='received'?'В продаже':rs==='at_warehouse'?'На складе':rs==='to_me'?'Едет ко мне':'Едет на склад',rb=rs==='received'?'ok':rs==='at_warehouse'?'teal':rs==='to_me'?'purple':'';return `<div class="purchase-line"><div class="grow"><b>${esc(productNameById(x.productId,'—'))}</b><div class="muted">${qty} шт. · закуп ${fmt(unitBuy)}/шт.</div>${partial?`<span class="badge ${rb}" style="margin-top:5px">${rl}</span>`:''}</div><div class="right"><div class="muted">с доставкой</div><b>${fmt(withDelivery)}/шт.</b></div></div>`}).join(''),deliveryLabel=status==='to_me'?'доставка к оплате':'доставка',edit=rows.some(x=>purchaseStatus(x)==='received')?'<div class="link-note">Часть поставки уже введена в продажу, поэтому состав и количество поставки больше не редактируются.</div>':`<button class="btn full" onclick="openEditPurchaseShipment('${key}')">Редактировать поставку</button>`,waitingRows=rows.filter(x=>purchaseStatus(x)==='at_warehouse'),waitingQty=waitingRows.reduce((a,x)=>a+Math.max(0,Number(x.qty)||0),0),holding=waitingRows.length?`<div class="link-note"><b>На складе, но ещё не в продаже: ${waitingRows.length} поз. · ${waitingQty} шт.</b><br>Можно вводить позиции в продажу по одной или несколько сразу. Невыбранные останутся на складе и не попадут в свободный остаток, FIFO и остатки маркетплейсов.</div>`:'',action=status==='to_forwarder'?`<button class="btn dark full" onclick="advancePurchaseShipment('${key}')">Приехал на склад доставщика</button>`:status==='to_me'?`<button class="btn dark full" onclick="openReceivePurchaseShipment('${key}')">Отметить: поступило на склад</button>`:waitingRows.length?`<button class="btn dark full" onclick="openReleasePurchaseShipment('${key}')">Выбрать позиции для продажи</button>`:'';showSheet(`<h3>${esc(first.batch||'Поставка')}</h3><div class="item"><div class="order-head"><div class="grow"><div class="muted">${dateLabel}: ${date?new Date(date).toLocaleDateString('ru-RU'):'—'}</div><div class="muted" style="margin-top:4px">${rows.length} поз. · ${t.qty} шт.</div></div><span class="badge ${badge}">${label}</span></div><div class="muted" style="margin-top:9px">Закупка: ${fmt(t.buy)} · ${deliveryLabel}: ${fmt(t.delivery)} · всего: ${fmt(t.buy+t.delivery)}</div><div class="purchase-lines">${lines}</div></div>${holding}${edit}${action}`)}'''
)

# Replace all-or-nothing release with a selection sheet and partial release.
replace_block(
    'function releasePurchaseShipment(encodedKey){',
    '\nfunction saleForm(',
    '''function openReleasePurchaseShipment(encodedKey){const rows=purchaseShipmentRows(encodedKey).filter(x=>purchaseStatus(x)==='at_warehouse');if(!rows.length)return alert('В этой поставке нет позиций, ожидающих ввода в продажу.');const first=rows[0],key=encodeURIComponent(String(first.shipmentId||first.id||'')),lines=rows.map(x=>{const qty=Math.max(0,Number(x.qty)||0),cost=Number(x.landedUnitCost)||Number(x.unitCost)||0;return `<label class="item row" style="margin-bottom:8px;cursor:pointer"><input type="checkbox" class="purchase-release-check" value="${esc(String(x.id))}" style="width:22px;height:22px;flex:none"><div class="grow"><b>${esc(productNameById(x.productId,'—'))}</b><div class="muted">${qty} шт. · себестоимость ${fmt(cost)}/шт.</div></div></label>`}).join('');showSheet(`<h3>Ввести в продажу</h3><div class="link-note">Отметьте только те позиции, которые уже выставили на продажу. Остальные останутся в статусе «Поступило на склад» и продолжат отображаться как «В пути».</div>${lines}<button class="btn dark full" onclick="releaseSelectedPurchaseRows('${key}')">Ввести выбранные позиции</button>`)}\nfunction releaseSelectedPurchaseRows(encodedKey){const rows=purchaseShipmentRows(encodedKey),ids=new Set([...document.querySelectorAll('.purchase-release-check:checked')].map(x=>String(x.value))),selected=rows.filter(x=>ids.has(String(x.id))&&purchaseStatus(x)==='at_warehouse');if(!selected.length)return alert('Выберите хотя бы одну позицию');const total=selected.reduce((a,x)=>a+Math.max(0,Number(x.qty)||0),0),names=selected.map(x=>productNameById(x.productId,'товар')).join(', ');if(!confirm(`Ввести выбранные позиции в продажу?\\n\\n${names}\\nВсего: ${total} шт.`))return;const releasedAt=Date.now();for(const x of selected){const p=prod(x.productId),qty=Math.max(0,Number(x.qty)||0);if(!p||!qty)continue;x.status='received';x.receivedAt=releasedAt;x.remainingQty=qty;p.stock=(Number(p.stock)||0)+qty;refreshProductAverageCost(p);log('приход',p.id,qty,`в продажу · поставка ${x.batch||x.shipmentId} · себестоимость ${fmt(Number(x.landedUnitCost)||Number(x.unitCost)||0)}/шт.`)}save();closeModal();render();const left=rows.filter(x=>purchaseStatus(x)==='at_warehouse').reduce((a,x)=>a+Math.max(0,Number(x.qty)||0),0);alert(left>0?`Выбранные позиции введены в продажу. На складе без продажи осталось ${left} шт.`:'Вся поставка теперь введена в продажу.')}\nfunction releasePurchaseShipment(encodedKey){openReleasePurchaseShipment(encodedKey)}'''
)

# Make purchase counters count only rows that are actually in each stage.
old="sumQty=a=>a.reduce((n,g)=>n+purchaseShipmentTotals(g).qty,0),inTransit=[...toForwarder,...toMe],inTransitValue=inTransit.reduce((n,g)=>n+purchaseShipmentTotals(g).buy,0),deliveryDue=purchaseDeliveryDue(allGroups),since=reportPeriodStart(30),received30=received.filter(g=>Number(g.receivedAt)>=since);"
new="sumQty=(a,status)=>a.reduce((n,g)=>n+(g.rows||[]).filter(x=>purchaseStatus(x)===status).reduce((m,x)=>m+Math.max(0,Number(x.qty)||0),0),0),inTransit=[...toForwarder,...toMe],inTransitValue=inTransit.reduce((n,g)=>n+(g.rows||[]).filter(x=>['to_forwarder','to_me'].includes(purchaseStatus(x))).reduce((m,x)=>m+(Number(x.buyTotal)||((Number(x.unitCost)||0)*(Number(x.qty)||0))),0),0),deliveryDue=purchaseDeliveryDue(allGroups),since=reportPeriodStart(30),received30Qty=(state.purchases||[]).filter(x=>purchaseStatus(x)==='received'&&Number(x.receivedAt)>=since).reduce((n,x)=>n+Math.max(0,Number(x.qty)||0),0);"
if old not in s:
    raise SystemExit('renderPurchases metric setup marker missing')
s=s.replace(old,new,1)
old="set('pToForwarder',sumQty(toForwarder).toLocaleString('ru-RU')+' шт.');set('pToMe',sumQty(toMe).toLocaleString('ru-RU')+' шт.');set('pAtWarehouse',sumQty(atWarehouse).toLocaleString('ru-RU')+' шт.');set('pInTransitValue',fmt(inTransitValue));set('pDeliveryDue',fmt(deliveryDue));set('pReceived30',sumQty(received30).toLocaleString('ru-RU')+' шт.');"
new="set('pToForwarder',sumQty(toForwarder,'to_forwarder').toLocaleString('ru-RU')+' шт.');set('pToMe',sumQty(toMe,'to_me').toLocaleString('ru-RU')+' шт.');set('pAtWarehouse',sumQty(atWarehouse,'at_warehouse').toLocaleString('ru-RU')+' шт.');set('pInTransitValue',fmt(inTransitValue));set('pDeliveryDue',fmt(deliveryDue));set('pReceived30',received30Qty.toLocaleString('ru-RU')+' шт.');"
if old not in s:
    raise SystemExit('renderPurchases metric values marker missing')
s=s.replace(old,new,1)

p.write_text(s,encoding='utf-8')
print('partial purchase release patch applied')
